// 시헌과 써니의 대탐험 — co-op server (one file: the game page is included at the bottom)
// One Durable Object per secret code (the browser sends only a SHA-256 hash of the code).
// It keeps the world: changed blocks, chests/crops, each player's bag, animals/pets, time and dungeon progress,
// and relays live positions and effects between the two players.
import { DurableObject } from "cloudflare:workers";

const clean = (s, n = 12) => String(s == null ? "" : s).replace(/[\u0000-\u001f\u007f<>]/g, " ").slice(0, n);
const safeId = (s) => String(s || "").replace(/[^a-zA-Z0-9]/g, "").slice(0, 24);
const MAX_PLAYERS = 4;

export class Island extends DurableObject {
  constructor(ctx, env) {
    super(ctx, env);
    this.ctx.setWebSocketAutoResponse(new WebSocketRequestResponsePair('{"t":"ping"}', '{"t":"pong"}'));
    this.seen = new Map(); // socket -> last time we heard from it (lost when the object sleeps; then the ping timestamps are used)
    this.lastSweep = 0;
  }
  // a connection counts as alive if it pinged or sent anything in the last 45 s; a phone that went to sleep
  // or lost signal never says goodbye, and without this its ghost would block the room ("full", no host)
  alive(ws, a) {
    let last = Math.max((a && a.joined) || 0, (a && a.seen) || 0);
    try { const t = this.ctx.getWebSocketAutoResponseTimestamp(ws); if (t) last = Math.max(last, t.getTime()); } catch (e) {}
    last = Math.max(last, this.seen.get(ws) || 0);
    return Date.now() - last < 45000;
  }
  sweep(force) {
    if (!force && Date.now() - this.lastSweep < 8000) return;
    this.lastSweep = Date.now();
    for (const ws of this.ctx.getWebSockets()) {
      const a = ws.deserializeAttachment();
      if (!a || !a.pid || this.alive(ws, a)) continue;
      const pid = a.pid; a.pid = null; ws.serializeAttachment(a);
      try { ws.close(4001, "stale"); } catch (e) {}
      if (!this.live().some((x) => x.a.pid === pid)) { this.broadcast({ t: "bye", id: pid }); this.broadcast({ t: "host", id: this.hostId() }); }
    }
  }
  async fetch(req) {
    if (req.headers.get("Upgrade") !== "websocket") return new Response("websocket only", { status: 426 });
    this.sweep(true);
    if (this.live().length >= MAX_PLAYERS) return new Response("full", { status: 429 });
    const pair = new WebSocketPair();
    const [client, server] = Object.values(pair);
    this.ctx.acceptWebSocket(server);
    server.serializeAttachment({ pid: null, joined: Date.now(), name: "", look: null });
    return new Response(null, { status: 101, webSocket: client });
  }
  live(except) {
    const out = [];
    for (const ws of this.ctx.getWebSockets()) {
      if (ws === except) continue;
      const a = ws.deserializeAttachment();
      if (a && a.pid && this.alive(ws, a)) out.push({ ws, a });
    }
    return out;
  }
  hostId(except) {
    const s = this.live(except).sort((x, y) => x.a.joined - y.a.joined);
    return s[0] ? s[0].a.pid : null;
  }
  send(ws, m) { try { ws.send(typeof m === "string" ? m : JSON.stringify(m)); } catch (e) {} }
  broadcast(m, except) { const s = JSON.stringify(m); for (const x of this.live(except)) this.send(x.ws, s); }
  async snapshot() {
    const st = this.ctx.storage;
    const edits = {};
    for (const [k, v] of await st.list({ prefix: "e:" })) {
      const [, L, p] = k.split(":");
      (edits[L] || (edits[L] = [])).push([+p, v]);
    }
    const tiles = [];
    for (const [k, v] of await st.list({ prefix: "t:" })) tiles.push([k.slice(2), v]);
    const players = {};
    for (const [k, v] of await st.list({ prefix: "p:" })) players[k.slice(2)] = v;
    const [time, ents, dg] = await Promise.all([st.get("time"), st.get("ents"), st.get("dg")]);
    return { edits, tiles, players, time: time || 60, ents: ents || [], dg: dg || {} };
  }
  async webSocketMessage(ws, raw) {
    if (typeof raw !== "string" || raw.length > 200000) return;
    let m;
    try { m = JSON.parse(raw); } catch (e) { return; }
    const a = ws.deserializeAttachment() || {};
    const st = this.ctx.storage;
    this.seen.set(ws, Date.now());
    if (a.pid && Date.now() - (a.seen || 0) > 15000) { a.seen = Date.now(); ws.serializeAttachment(a); }// survives the object going to sleep
    this.sweep(false);
    if (m.t === "hello") {
      a.pid = safeId(m.pid) || crypto.randomUUID().slice(0, 8);
      a.name = clean(m.name, 8);
      a.look = m.look && typeof m.look === "object" ? m.look : null;
      a.joined = Date.now();
      // my own older connection (I reconnected): forget it right away so it can't hold my place or the host role
      for (const old of this.ctx.getWebSockets()) {
        if (old === ws) continue;
        const b = old.deserializeAttachment();
        if (b && b.pid === a.pid) { b.pid = null; old.serializeAttachment(b); try { old.close(4000, "moved"); } catch (e) {} }
      }
      ws.serializeAttachment(a);
      const [meta, opts, snap] = await Promise.all([st.get("meta"), st.get("opts"), this.snapshot()]);
      const peers = this.live(ws).filter((x) => x.a.pid !== a.pid).map((x) => ({ id: x.a.pid, name: x.a.name, look: x.a.look }));
      // a big world goes over in pieces (one websocket message can only be so large)
      const all = []; for (const L in snap.edits) for (const e of snap.edits[L]) all.push([+L, e[0], e[1]]);
      const CH = 15000, parts = Math.ceil(all.length / CH);
      snap.edits = {};
      this.send(ws, { t: "welcome", meta: meta || null, opts: opts || null, snap, peers, host: this.hostId(), parts });
      for (let i = 0; i < parts; i++) this.send(ws, { t: "snapE", i, list: all.slice(i * CH, (i + 1) * CH) });
      this.broadcast({ t: "host", id: this.hostId() });
      return;
    }
    if (!a.pid) return;
    m.from = a.pid;
    const isHost = a.pid === this.hostId();
    switch (m.t) {
      case "create":
        if (!(await st.get("meta")) && m.meta && typeof m.meta.seed === "number") await st.put({ meta: { name: clean(m.meta.name, 16), seed: m.meta.seed | 0, created: Date.now() }, opts: m.opts || {} });
        return;
      case "edit":
        if (typeof m.p !== "number" || typeof m.b !== "number") return;
        await st.put("e:" + (m.L | 0) + ":" + m.p, m.b | 0);
        break;
      case "tile":
        if (typeof m.k !== "string" || m.k.length > 60) return;
        if (m.v == null) await st.delete("t:" + m.k); else await st.put("t:" + m.k, m.v);
        break;
      case "pl":
        if (m.data && typeof m.data === "object") { await st.put("p:" + a.pid, m.data); if (m.data.look) { a.look = m.data.look; a.name = clean(m.data.name, 8); ws.serializeAttachment(a); } }
        return;
      case "time": if (!isHost) return; await st.put("time", +m.v || 0); break;
      case "ents": if (!isHost) return; await st.put("ents", Array.isArray(m.list) ? m.list.slice(0, 200) : []); return;
      case "es": if (!isHost) return; break;
      case "dg": { const dg = (await st.get("dg")) || {}; dg[m.L | 0] = m.v; await st.put("dg", dg); break; }
      case "ping": return;
      case "delpl": {
        const id = safeId(m.id);
        if (!id || id === a.pid || this.live().some((x) => x.a.pid === id)) { this.send(ws, { t: "delres", ok: false, id }); return; }
        await st.delete("p:" + id);
        this.send(ws, { t: "delres", ok: true, id });
        return;
      }
      // 섬 되돌리기: the whole island (blocks, chests, every bag) goes back to how it was at the chosen time.
      // Cloudflare keeps 30 days of history for this storage; the answer carries an "undo" mark to come back to now.
      case "rollback": case "unrollback": {
        try {
          let bm;
          if (m.t === "rollback") { const at = +m.at; if (!(at > Date.now() - 29 * 864e5 && at < Date.now() - 30000)) { this.send(ws, { t: "rbres", ok: false, err: "time" }); return; } bm = await st.getBookmarkForTime(at); }
          else { bm = typeof m.bm === "string" ? m.bm : ""; if (!bm) return; }
          const undo = await st.onNextSessionRestoreBookmark(bm);
          for (const x of this.live()) this.send(x.ws, { t: "rbres", ok: true, undo, at: +m.at || 0, kind: m.t, by: a.name });
          await new Promise((r) => setTimeout(r, 600));
          this.ctx.abort("island restored");
        } catch (e) { this.send(ws, { t: "rbres", ok: false, err: String((e && e.message) || e).slice(0, 160) }); }
        return;
      }
    }
    const out = JSON.stringify(m);
    if (m.to) { for (const x of this.live()) if (x.a.pid === m.to) this.send(x.ws, out); return; }
    if (m.toHost) { const h = this.hostId(); for (const x of this.live()) if (x.a.pid === h) this.send(x.ws, out); return; }
    this.broadcast(m, ws);
  }
  async webSocketClose(ws) { this.left(ws); }
  async webSocketError(ws) { this.left(ws); }
  left(ws) {
    const a = ws.deserializeAttachment();
    if (!a || !a.pid) return;
    if (this.live(ws).some((x) => x.a.pid === a.pid)) return;
    this.broadcast({ t: "bye", id: a.pid }, ws);
    this.broadcast({ t: "host", id: this.hostId(ws) }, ws);
  }
}

export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (url.pathname === "/ws") {
      const room = (url.searchParams.get("room") || "").replace(/[^a-f0-9]/g, "").slice(0, 40);
      if (room.length < 16) return new Response("bad room", { status: 400 });
      return env.ISLAND.get(env.ISLAND.idFromName(room)).fetch(req);
    }
    if (url.pathname !== "/" && url.pathname !== "/index.html") return new Response("not found", { status: 404 });
    return new Response(PAGE.replaceAll("__ORIGIN__", url.origin), { headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-cache" } });
  },
};

